import React, { useState, useEffect, useRef } from "react";
import { MapContainer, TileLayer, GeoJSON, LayersControl } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";
import { useMapEvents } from "react-leaflet";

function ZoomWatcher({ onZoomChange }) {
  useMapEvents({
    zoomend: (e) => {
      const newZoom = e.target.getZoom();
      onZoomChange(newZoom);
    },
  });
  return null;
}
function getWinnersFromGeoJSON(features, prefix = "2013_mer_") {
  const winners = new Set();

  for (const feature of features) {
    const props = feature.properties;
    const scores = {};

    for (const key in props) {
      if (key.startsWith(prefix)) {
        const name = key.replace(prefix, "");
        if (!/^[А-ЯЁ]/.test(name)) continue;  // добавляем фильтр по заглавной букве
        scores[name] = props[key];
      }
    }

    const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
    if (sorted.length > 0) {
      const winner = sorted[0][0];
      winners.add(winner);
    }
  }

  return Array.from(winners);
}


function getAdvantageLevels(features, prefix = "2013_mer_") {
  const levels = {};

  for (const feature of features) {
    const props = feature.properties;
    const scores = {};

    for (const key in props) {
      if (key.startsWith(prefix)) {
        const name = key.replace(prefix, "");
        if (!/^[А-ЯЁ]/.test(name)) continue; // Игнорируем не-кандидатов
        scores[name] = props[key];
      }
    }

    const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
    if (sorted.length < 2) continue;

    const winner = sorted[0][0];
    const advantage = sorted[0][1] - sorted[1][1];

    let level = 1;
    if (advantage >= 20) level = 4;
    else if (advantage >= 10) level = 3;
    else if (advantage >= 5) level = 2;

    if (!levels[winner] || levels[winner] < level) {
      levels[winner] = level;
    }
  }

  return levels;
}




const baseColors = {
  Собянин: "#0072bc",
  Навальный: "#f28c28",
  Мельников: "#d73027"
};

function shadeColor(hex, alpha) {
  if (!hex) return "#cccccc"; // Защита от undefined

  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}
const getWinnerColorByAdvantage = (props) => {
  const candidates = {
    Собянин: props["2013_mer_Собянин"] || 0,
    Навальный: props["2013_mer_Навальный"] || 0,
    Мельников: props["2013_mer_Мельников"] || 0,
  };
  const sorted = Object.entries(candidates).sort((a, b) => b[1] - a[1]);
  const winner = sorted[0][0];
  const advantage = sorted[0][1] - sorted[1][1];
  const baseColors = {
    Собянин: "#0072bc",
    Навальный: "#f28c28",
    Мельников: "#d73027",
  };
  const color = baseColors[winner];
  const steps = [
    [5, 0.2],
    [10, 0.4],
    [15, 0.6],
    [100, 0.85],
  ];
  const alpha = steps.find(([limit]) => advantage < limit)?.[1] || 1;
  return shadeColor(color, alpha);
};

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState(null);
  const [activeDataType, setActiveDataType] = useState("Победитель");
  const [activeElectionLevel, setActiveElectionLevel] = useState("Госдума");
  const [activeListType, setActiveListType] = useState("Округ");
  const [mapZoom, setMapZoom] = useState(10);
  const [districtData, setDistrictData] = useState(null);
  const [uikData, setUikData] = useState(null);
  const [legendLevels, setLegendLevels] = useState({});
  const [districtLegendLevels, setDistrictLegendLevels] = useState({});
  const mapRef = useRef();

  useEffect(() => {
    if (year === 2013 && activeElectionLevel === "Мэр") {
      fetch("/data/districts_with_2013_mer.geojson")
		.then((res) => res.json())
		.then((data) => {
			setDistrictData(data);
			const levels = getAdvantageLevels(data.features);
			setDistrictLegendLevels(levels);
		 });


      fetch("/data/united_uiks_with_final_2013_mer.geojson")
        .then((res) => res.json())
        .then((data) => setUikData(data));
	  fetch("/data/united_uiks_with_final_2013_mer.geojson")
		.then((res) => res.json())
		.then((data) => {
			setUikData(data);
			const levels = getAdvantageLevels(data.features);
			setLegendLevels(levels);
  });
    }
  }, [year, activeElectionLevel]);

  const showDistrictLayer = year === 2013 && activeElectionLevel === "Мэр";
  const showPrecinctLayer = showDistrictLayer && mapZoom > 13;

  return (
    <div className="App">
      <div className="title-wrapper">
        <div className="title-decorated">
          <h1>Выборы Москвы</h1>
        </div>
      </div>

      {/* Слайдер */}
      <div className="slider-container">
        <label>Год: {year}</label>
        <Slider
          className="slider"
          value={year}
          min={2012}
          max={2022}
          step={1}
          onChange={setYear}
          renderTrack={(props) => <div {...props} className="slider-track" />}
          renderThumb={(props) => <div {...props} className="slider-thumb" />}
        />
      </div>

      {/* Карта + панели */}
      <div className="map-wrapper">
        <div className="map-container">
          {/* Верхняя панель */}
          <div className="top-controls">
            {["Явка", "Победитель", "Процент испорченных бюллетеней"].map((label) => (
              <button
                key={label}
                className={activeDataType === label ? "active" : ""}
                onClick={() => setActiveDataType(label)}
              >
                {label}
              </button>
            ))}
          </div>

          {activeElectionLevel === "Госдума" && (
            <div className="center-controls">
              {["Округ", "Список"].map((label) => (
                <button
                  key={label}
                  className={activeListType === label ? "active" : ""}
                  onClick={() => setActiveListType(label)}
                >
                  {label}
                </button>
              ))}
            </div>
          )}

          {/* Боковая панель */}
          <div className="controls">
            {["Госдума", "Мосгордума", "Муниципальные", "Мэр", "Президент"].map((label) => (
              <button
                key={label}
                className={activeElectionLevel === label ? "active" : ""}
                onClick={() => setActiveElectionLevel(label)}
              >
                {label}
              </button>
            ))}
          </div>

          {/* Leaflet карта */}
          <MapContainer
            center={[55.7558, 37.6173]}
            zoom={10}
            className="map-container"
            whenCreated={(map) => {
              mapRef.current = map;
              map.on("zoomend", () => setMapZoom(map.getZoom()));
            }}

          >
			{showDistrictLayer && districtData && !showPrecinctLayer && (
			  <GeoJSON
				data={districtData}
				style={(feature) => {
				  const props = feature.properties;

				  // Победитель (старое поведение)
				  if (activeDataType === "Победитель") {
					return {
					  color: "#000",
					  weight: 2,
					  fillOpacity: 1,
					  fillColor: getWinnerColorByAdvantage(props),
					};
				  }

				  // Явка
				  if (activeDataType === "Явка") {
					const value = props["2013_mer_явка"];
					let fill = "#e6f4ea";
					if (value >= 65) fill = "#21814f";
					else if (value >= 50) fill = "#3a9d66";
					else if (value >= 35) fill = "#5bbf83";
					else if (value >= 20) fill = "#a6d9b7";
					return {
					  color: "#000",
					  weight: 2,
					  fillOpacity: 1,
					  fillColor: fill
					};
				  }

				  // Недействительные бюллетени
				  if (activeDataType === "Процент испорченных бюллетеней") {
					const value = props["2013_mer_недействительные"];
					let fill = "#fde8ef";
					if (value >= 2) fill = "#c51b8a";
					else if (value >= 1.5) fill = "#ef6cae";
					else if (value >= 1) fill = "#f7b6cf";
					else if (value >= 0.5) fill = "#fcd2e1";
					return {
					  color: "#000",
					  weight: 2,
					  fillOpacity: 1,
					  fillColor: fill
					};
				  }

				  // Значение по умолчанию
				  return {
					color: "#000",
					weight: 2,
					fillOpacity: 0.6,
					fillColor: "#ccc"
				  };
				}}
			  />
			)}


			{showPrecinctLayer && activeDataType === "Победитель" && (
			  <div className="legend-box-horizontal">
				<h4>Преимущество победителя</h4>
				<div className="legend-horizontal">
				  {Object.entries(legendLevels).map(([name, level]) => (
					<div className="legend-candidate" key={name}>
					  {Array.from({ length: level }, (_, i) => {
						const alpha = [0.2, 0.4, 0.6, 0.85][i];
						const label = ["менее 5", "5–10", "10–20", "более 20"][i];
						return (
						  <div key={i} className="legend-entry">
							<div
							  className="legend-color-box"
							  style={{ backgroundColor: shadeColor(baseColors[name], alpha) }}
							></div>
							<div className="legend-label">{label}%</div>
						  </div>
						);
					  })}
					  <div className="legend-name">{name}</div>
					</div>
				  ))}
				</div>
			  </div>
			)}

            <TileLayer
              attribution='Tiles &copy; Esri — Esri, DeLorme, NAVTEQ'
              url="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}"
            />
            <ZoomWatcher onZoomChange={setMapZoom} />


            {showPrecinctLayer && uikData && (
			  <GeoJSON
				data={uikData}
				style={(feature) => {
				  const props = feature.properties;

				  // Победитель (старая логика)
				  if (activeDataType === "Победитель") {
					return {
					  color: "#333",
					  weight: 1,
					  fillOpacity: 1,
					  fillColor: getWinnerColorByAdvantage(props),
					};
				  }

				  // Явка
				  if (activeDataType === "Явка") {
					const value = props["2013_mer_явка"];
					let fill = "#e6f4ea";
					if (value >= 65) fill = "#21814f";
					else if (value >= 50) fill = "#3a9d66";
					else if (value >= 35) fill = "#5bbf83";
					else if (value >= 20) fill = "#a6d9b7";
					return {
					  color: "#333",
					  weight: 1,
					  fillOpacity: 1,
					  fillColor: fill
					};
				  }

				  // Недействительные бюллетени
				  if (activeDataType === "Процент испорченных бюллетеней") {
					const value = props["2013_mer_недействительные"];
					let fill = "#fde8ef";
					if (value >= 2) fill = "#c51b8a";
					else if (value >= 1.5) fill = "#ef6cae";
					else if (value >= 1) fill = "#f7b6cf";
					else if (value >= 0.5) fill = "#fcd2e1";
					return {
					  color: "#333",
					  weight: 1,
					  fillOpacity: 1,
					  fillColor: fill
					};
				  }

				  // Значение по умолчанию
				  return {
					color: "#333",
					weight: 1,
					fillOpacity: 0.5,
					fillColor: "#ddd"
				  };
				}}
			  />
			)}


          </MapContainer>


        </div>
      </div>
    </div>
  );
}

export default App;
